import { useState, useEffect } from "react";
import { FormControl, Grid, MenuItem, Paper, Select, styled } from "@mui/material";
import arrayShuffle from "array-shuffle";
import { Button, Slider } from "@mui/material";
import Swal from "sweetalert2";
import { ToastContainer } from "react-toastify";
import { useNavigate } from "react-router-dom";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import jsondata from "../json/conjunction_level1.json";
import { useTranslation } from "react-i18next";
import parse from "html-react-parser";

const Level1 = () => {
  // Load Json to mainArr variable ....
  var [mainArr, setmainArr] = useState([]);
  var [correctconj, setCorrectconj] = useState([]);
  var [wordpool, setWordpool] = useState(new Set());
  var [shuffledwordpool, setShuffledwordpool] = useState(Array.from({ length: 5 }));
  var [currentsentence, setCurrentsentence] = useState("");
  var [count, setCount] = useState([]);
  var [datalength, setDatalength] = useState();
  let [visitedno, setVisitedno] = useState([]);
  var [score, setScore] = useState(0);
  var [flag, setFlag] = useState(false);
  var [flag1, setFlag1] = useState(false);
  var [showfeedback, setShowfeedback] = useState(0);
  var [currentotherwords, setCurrentotherwords] = useState([]);
  var [currentconjwords, setCurrentconjwords] = useState([]);
  var [feedback, setFeedback] = useState();
  var [progress, setProgress] = useState(0);
  var [clsnm, setClsnm] = useState([false, false, false, false, false]);
  var [clrnm, setClrnm] = useState([0, 0, 0, 0, 0]);
  const navigate = useNavigate();
  var no;
  let [level, setLevel] = useState("Level 1");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Level 1 page");
  const { t, i18n } = useTranslation();

  useEffect(() => {
    mainArr = jsondata.results;
    setmainArr(mainArr);
    populate(mainArr);
  }, []);

  function populate(maindata) {
    datalength = maindata.length - 1;
    setDatalength(datalength);
    let status = true;
    do {
      no = randomNumberInRange(0, datalength);
      if (!visitedno.includes(no)) {
        visitedno = [...visitedno, no];
        setVisitedno(visitedno);
        let tempotherarr = [];
        for (var i = 0; i < maindata[no].other_array.length; i++) {
          const rrr = maindata[no].other_array[i];
          tempotherarr.push(rrr);
        }
        currentotherwords = tempotherarr;
        setCurrentotherwords(currentotherwords);
        let tempCorrectconj = [];
        let tempCorrectconjqueue = [];
        for (var i = 0; i < maindata[no].conjunctions.length; i++) {
          const correctconjValue = maindata[no].conjunctions[i].word;
          const correctconjqueue = maindata[no].conjunctions[i];
          tempCorrectconj.push(correctconjValue);
          wordpool.add(correctconjValue);
          tempCorrectconjqueue.push(correctconjqueue);
        }
        correctconj = tempCorrectconj;
        setCorrectconj(correctconj);
        currentconjwords = tempCorrectconjqueue;
        setCurrentconjwords(currentconjwords);
        currentsentence = maindata[no].sentence_doc;
        setCurrentsentence(currentsentence);
        var tempsent = currentsentence.replace(/[.,]/g, ""); // removing . and , from the sentences using regex
        var vals = tempsent.split(" ");
        // Shuffle the array
        var tempval = arrayShuffle(vals);

        // Iterate through the shuffled array and add unique words to wordpool
        var temcount = wordpool.size;
        tempval.forEach((word) => {
          if (
            !correctconj.includes(word) &&
            temcount < 5 &&
            !wordpool.has(word)
          ) {
            wordpool.add(word);
            temcount = temcount + 1;
          }
        });
        setWordpool(wordpool);
        var changedpool = wordpool;
        let myArr = Array.from(changedpool);
        var shufflewords = arrayShuffle(myArr);
        shuffledwordpool = shufflewords;
        setShuffledwordpool(shuffledwordpool);
        status = false;
        setProgress(progress + 1);
      }
    } while (status);
  }

  function randomNumberInRange(min, max) {
    // get number between min (inclusive) and max (inclusive)
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  const Item = styled(Paper)(({ theme, backgroundColor }) => ({
    backgroundColor: theme.palette.mode === "dark" ? "#1A2027" : "#d1dcfc",
    ...theme.typography.body2,
    padding: theme.spacing(2),
    textAlign: "center",
    color: theme.palette.text.secondary,
  }));

  const handleOnClick = (e, item) => {
    var tempclrnm = clrnm;
    var tempclsnm = clsnm;
    var locofword = getIndex(item);
    if (correctconj.includes(item)) {
      var curcnt = count;
      tempclsnm[locofword] = true;
      tempclrnm[locofword] = 1;
      setClsnm(tempclsnm);
      setClrnm(tempclrnm);
      curcnt = [...curcnt, 1];
      setCount(curcnt);
      if (correctconj.length != 0) {
        const selected_word = document.getElementById(item);
        let selectedword = null;
        let selectedword_type = null;
        for (var i = 0; i < currentconjwords.length; i++) {
          const currentObject = currentconjwords[i];
          for (const key in currentObject) {
            if (selected_word.id === currentObject.word) {
              selectedword_type = currentObject.POS;
              selectedword = selected_word.id;
            }
          }
        }
        if (curcnt.length === correctconj.length) {
          ReactGA.event({
            action:
              "English Conjunction | CDAC-OlabsNxtG-En-20 | selected all conjunctions",
            category:
              "English CDAC-OlabsNxtG-En-20 | level-1 selected all conjunctions",
            label:
              "English CDAC-OlabsNxtG-En-20 | level-1 selected all conjunctions for current sentence",
          });
          SendLogData(
            sendJsonMessage,
            pageName,
            `All "${correctconj}" words added`,
            "Clicked",
            `Click on all "${correctconj}" Buttons.`
          );
          Swal.fire({
            position: "top-center",
            icon: "success",
            title:
              "Wow! You have selected all correct conjunctions in the given sentence.",
            text: 'Now you can click on "NEXT" button',
            showConfirmButton: true,
          });
          flag = true;
          setFlag(flag);
        }
        showfeedback = 1;
        setShowfeedback(showfeedback);;
        var text =
          '<div>Correct <span style="color:green;"><b>' +
          `${selectedword}` +
          '</b></span>' +
          ' is a conjunction, <br/> and Its type is ' +
          `${selectedword_type}` +
          '</div>';
        feedback = text;
        setFeedback(feedback);
      }
    } else {
      const anyword = document.getElementById(item);
      var name = anyword.id;
      if (name.includes("'")) {
        let nameword = null;
        let nameword_type = null;
        tempclrnm[locofword] = 2;
        setClrnm(tempclrnm);
        showfeedback = 2;
        setShowfeedback(showfeedback);
        for (var i = 0; i < currentotherwords.length; i++) {
          const currentObject = currentotherwords[i];
          for (const key in currentObject) {
            if (name === key) {
              nameword_type = currentObject[key];
              nameword = name;
            }
          }
        }
        var text =
          '<div><span style="color:red;"><b>' +
          `${name}` +
          '</b></span>' +
          ' is not a conjunction. <br/> But it is combination of two words where ' +
          `${nameword_type}` +
          '</div>';
      } else {
        const selected_word = document.getElementById(item);
        let selectedword = null;
        let selectedword_type = null;
        for (var i = 0; i < currentotherwords.length; i++) {
          const currentObject = currentotherwords[i];
          for (const key in currentObject) {
            if (selected_word.id === key) {
              selectedword_type = currentObject[key];
              selectedword = selected_word.id;
            }
          }
        }
        tempclrnm[locofword] = 2;
        setClrnm(tempclrnm);
        showfeedback = 2;
        setShowfeedback(showfeedback);
        const isVowel = /^[aeiouAEIOU]/.test(selectedword_type);
        const article = isVowel ? "an" : "a";
        var text =
          '<div>Incorrect <span style="color:red;"><b>' +
          `${selectedword}` +
          '</b></span>' +
          ' is ' + article + ' ' +
          `${selectedword_type}` +
          ', not a conjunction.</div>';
      }
      feedback = text;
      setFeedback(feedback);
    }
  };

  function getIndex(item) {
    const isLargeNumber = (element) => element === item;
    const idx = shuffledwordpool.findIndex(isLargeNumber);
    return idx;
  }

  const nextbtn = () => {
    setClsnm([false, false, false, false, false]);
    setClrnm([0, 0, 0, 0, 0]);
    count = [];
    setCount(count);
    flag = false;
    setFlag(flag);
    showfeedback = 0;
    setShowfeedback(showfeedback);
    feedback = "";
    setFeedback(feedback);
    score = score + 1;
    setScore(score);
    if (visitedno.length === datalength + 1) {
      flag1 = true;
      setFlag1(flag1);
    } else {
      ReactGA.event({
        action:
          'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Next" button.',
        category:
          'English CDAC-OlabsNxtG-En-20 | level-1 "Next" button clicked',
        label:
          'English CDAC-OlabsNxtG-En-20 | level-1 "Next" button clicked for next sentence.',
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "Next",
        "Clicked",
        "Click on Next Button."
      );
      setShuffledwordpool([]);
      setCorrectconj([]);
      wordpool.clear();
      populate(mainArr);
    }
  };

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Restart" button.',
      category:
        'English CDAC-OlabsNxtG-En-20 | level-1 "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-20 | level-1 "Restart" button clicked after level 1 completion',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      "Restart",
      "Clicked",
      "Click on Restart Button after completion of level 1."
    );
    window.location.reload();
  };

  const skipbtn = () => {
    setProgress(progress + 1);
    count = [];
    setCount(count);
    flag = false;
    setFlag(flag);
    showfeedback = 0;
    setShowfeedback(showfeedback);
    feedback = "";
    setFeedback(feedback);
    setClrnm([0, 0, 0, 0, 0]);
    if (visitedno.length == datalength + 1) {
      flag1 = true;
      setFlag1(flag1);
    } else {
      ReactGA.event({
        action:
          'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Skip" button.',
        category:
          'English CDAC-OlabsNxtG-En-20 | level-1 "Skip" button clicked',
        label:
          'English CDAC-OlabsNxtG-En-20 | level-1 "Skip" button clicked for next sentence.',
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        "Skip",
        "Clicked",
        "Click on Skip Button."
      );
      shuffledwordpool = [];
      setShuffledwordpool(shuffledwordpool);
      correctconj = [];
      setCorrectconj(correctconj);
      wordpool.clear();
      populate(mainArr);
    }
  };

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        ReactGA.event({
          action:
            'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Level 2" button.',
          category:
            'English CDAC-OlabsNxtG-En-20 | level-1 "Level 2" button clicked',
          label:
            'English CDAC-OlabsNxtG-En-20 | level-1 "Level 2" button clicked from levels dropdown',
        });
        SendLogData(
          sendJsonMessage,
          pageName,
          "Level 2 dropdown option",
          "Clicked",
          "Click on Level 2 Button from levels dropdown."
        );
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
  };

  return (
    <div
      className="row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className=""
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            position: "relative",
          }}
        >
          <div className="row-md-auto d-flex text-center">
            <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
              <b>{t("level_1_title")}</b>
            </div>

            <div className="d-flex justify-content-end">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                    fontSize: "calc(.6rem + .4vw)"
                  }}
                >
                  <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>

          {flag1 == true ? (
            <div
              className="text-center d-flex justify-content-center align-items-center"
              style={{ marginTop: "7%" }}
            >
              <div className="row" style={{ height: "100%" }}>
                <div className="d-flex justify-content-center align-items-center">
                  <div
                    className="col-md-auto text-center "
                    style={{
                      boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                      padding: "7vh 4vh 7vh 4vh",
                      backgroundColor: "#EDF6FA",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    <p style={{ fontWeight: "bolder" }}>
                      You have scored {score} out of {mainArr.length - 1}{" "}
                      sentences.
                    </p>
                    <div>
                      <Button variant="contained" onClick={restartbtn} style={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}>
                        {t("restart")}
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <>
              <div
                className="d-flex align-items-center"
                style={{ marginTop: "7%", fontSize: "calc(.6rem + .4vw)" }}
              >
                <span className="me-3">Sentence</span>

                <Slider
                  defaultValue={1}
                  step={1}
                  min={1}
                  max={jsondata.results.length}
                  value={progress}
                  marks
                  color="success"
                  valueLabelDisplay="on"
                  sx={{
                    "& .MuiSlider-mark": {
                      width: 12,
                      height: 12,
                      borderRadius: "50%",
                    },
                  }}
                />
                <span
                  className="ms-3"
                  style={{
                    height: "40px",
                    width: "60px",
                    borderRadius: "50%",
                    backgroundColor: "lightblue",
                    fontSize: "16px",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    fontSize: "calc(.6rem + .4vw)"
                  }}
                >
                  {progress}/{mainArr.length}
                </span>
              </div>

              <div
                className="row-md-auto text-center"
                style={{
                  borderRadius: "13px",
                  boxShadow: "0px 3px 6px #00000029",
                  display: "block",
                  marginLeft: "auto",
                  fontWeight: "bolder",
                  fontFamily: "Arial",
                  marginRight: "auto",
                  marginTop: "5%",
                  padding: "2%",
                  backgroundColor: "#EDF6FA",
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                {currentsentence}
              </div>

              <div
                className="row-md-auto justify-content-around "
                style={{
                  backgroundColor: "#EDF6FA",
                  borderRadius: "13px",
                  boxShadow: "0px 3px 6px #00000029",
                }}
              >
                <div className="row-md-auto" style={{ marginTop: "10px" }}>
                  <div className="p-2 mt-2" style={{ fontSize: "calc(.6rem + .4vw)" }}>Wordpool</div>
                  <div className="row-md-auto d-flex justify-content-around text-center">
                    {shuffledwordpool &&
                      shuffledwordpool.slice(0, 3).map((item, index) => (
                        <Grid
                          className="d-flex justify-content-center align-items-center "
                          container
                          spacing={1}
                          key={index}
                        >
                          <Grid item s={4}>
                            <Button
                              onClick={(e) => handleOnClick(e, item)}
                              id={item}
                              style={{
                                backgroundColor:
                                  clrnm[index] === 0
                                    ? "#F5B946"
                                    : clrnm[index] === 1
                                      ? "#098B0D"
                                      : "#BF4C4C",
                                color:
                                  clrnm[index] === 0
                                    ? "black"
                                    : clrnm[index] === 1
                                      ? "white"
                                      : "white",
                                borderRadius: "5px",
                                textAlign: "center",
                                boxSizing: "border-box",
                                textTransform: "none",
                                padding: "15%",
                                fontSize: "calc(.6rem + .4vw)"
                              }}
                            >
                              {item}
                            </Button>
                          </Grid>
                        </Grid>
                      ))}
                  </div>
                </div>
                <div
                  className="row-md-auto d-flex justify-content-around text-center "
                  style={{ margin: "15px" }}
                >
                  {shuffledwordpool &&
                    shuffledwordpool.slice(3, 5).map((item, index) => (
                      <Grid
                        className="d-flex justify-content-center align-items-center mb-2"
                        container
                        spacing={1}
                        key={index}
                      >
                        <Grid item s={4}>
                          <Button
                            className={clsnm == 1 ? "clsname0" : ""}
                            onClick={(e) => handleOnClick(e, item)}
                            id={item}
                            style={{
                              backgroundColor:
                                clrnm[index + 3] === 0
                                  ? "#F5B946"
                                  : clrnm[index + 3] === 1
                                    ? "#098B0D"
                                    : "#BF4C4C",
                              color:
                                clrnm[index + 3] === 0
                                  ? "black"
                                  : clrnm[index + 3] === 1
                                    ? "white"
                                    : "white",
                              borderRadius: "5px",
                              textAlign: "center",
                              boxSizing: "border-box",
                              textTransform: "none",
                              padding: "15%",
                              fontSize: "calc(.6rem + .4vw)"
                            }}
                          >
                            {item}
                          </Button>
                        </Grid>
                      </Grid>
                    ))}
                </div>
              </div>

              <div
                className="row-md-auto d-flex justify-content-around text-center"
                style={{ marginTop: "2%" }}
              >
                <div style={{ position: "right" }}>
                  <Button
                    variant="contained"
                    onClick={skipbtn}
                    sx={{ backgroundColor: "#0F477E", marginTop: "2%", fontSize: "calc(.6rem + .4vw)" }}
                    disabled={flag}
                  >
                    {t("skip")}
                  </Button>
                </div>

                <div style={{ position: "right" }}>
                  <Button
                    variant="contained"
                    onClick={nextbtn}
                    sx={{ backgroundColor: "#0F477E", marginTop: "2%", fontSize: "calc(.6rem + .4vw)" }}
                    disabled={flag == true ? false : true}
                  >
                    {t("next")}
                  </Button>
                </div>
              </div>

              <div
                className="row justify-content-center align-items-center text-center"
                id="feedbackbox"
                style={{
                  width: "80%", // Adjust the width as needed
                  maxWidth: "400px", // Set a maximum width if necessary
                  background: "#ffffff",
                  boxShadow: "0px 0px 13px rgba(0, 0, 0, 0.5)",
                  borderRadius: "50px", // Adjust the border radius as needed
                  padding: "2%",
                  display:
                    showfeedback === 1 || showfeedback === 2 ? "block" : "none",
                  margin: "auto", // Center the div horizontally
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                {parse("" + feedback)}
              </div>
            </>
          )}
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className=""
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", fontSize: "calc(.6rem + .4vw)" }}>
            <div>
              {flag1 == true ? (
                <ul className="">
                  <li>{t("instruction_1_8")}</li>
                </ul>
              ) : flag == true ? (
                <ul className="">
                  <li>{t("instruction_1_6")}</li>
                </ul>
              ) : (
                <ul className="">
                  <li>{t("instruction_1_1")}</li>
                  <li>{t("instruction_1_2")}</li>
                  <li>{t("instruction_1_3")}</li>
                  <li>{t("instruction_1_4")}</li>
                  <li>{t("instruction_1_5")}</li>
                  <li><u>{t("note")}</u>: {t("instruction_1_7")}</li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* <InfoPopUpForDetailView
  openDialog={showDialogue}
  onAgree={onAgree}
  content={<ViewDetailsPopup sentence={sentence} />}
  popuptitle="Hint"
/> */}
      <ToastContainer />
    </div>
  );
};

export default Level1;
