import { useState, useEffect } from "react";
import { FormControl, Grid, MenuItem, Select } from "@mui/material";
import arrayShuffle from "array-shuffle";
import { Button, Slider } from "@mui/material";
import jsondata from "../json/conjucntion_level2.json";
import { useNavigate } from "react-router-dom";
import "react-super-responsive-table/dist/SuperResponsiveTableStyle.css";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";

const Level2 = () => {
  // Load Json to mainArr variable ....
  let [mainArr, setMainArr] = useState([]);
  var [twoSentence, setTwosentence] = useState();
  var [sentence, setSentence] = useState();
  var [shuffledwords, setShuffledwords] = useState([]);
  var [correctconj, setCorrectconj] = useState([]);
  var [corrconjtype, setCorrconjtype] = useState();
  var [image, setImage] = useState("");
  var [splitsentence, setSplitsentence] = useState([]);
  var [count, setCount] = useState(0);
  var [datalength, setDatalength] = useState();
  var [blankval, setBlankval] = useState([]);
  var [datalength, setDatalength] = useState();
  var [flag1, setFlag1] = useState(false);
  var [progress, setProgress] = useState(0);
  var [score, setScore] = useState(0);
  var [flag2, setFlag2] = useState(false);
  var [updatedSplitsentence, setUpdatedSplitsentence] = useState([]);
  var [conditionMatches, setConditionMatches] = useState(false);
  var allwords;
  var [track, setTrack] = useState([]);
  var [idword, setIdword] = useState([]);
  var [disabledBlanks, setDisabledBlanks] = useState();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 2 page");
  const [test1, setTest1] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [currsentfeedback, setCurrsentfeedback] = useState();
  let [level, setLevel] = useState("Level 2");
  const navigate = useNavigate();
  const { t, i18n } = useTranslation();

  useEffect(() => {
    mainArr = arrayShuffle(jsondata);
    setMainArr(mainArr);
    populate(mainArr);
  }, []);

  useEffect(() => {
    setIsCorrect(arraysAreEqual(track, correctconj));
  }, [track, correctconj]);

  function populate(maindata) {
    twoSentence = maindata[count].twosentence;
    setTwosentence(twoSentence);
    sentence = maindata[count].sentence;
    setSentence(sentence);
    corrconjtype = maindata[count].conjunction.type;
    setCorrconjtype(corrconjtype);
    image = maindata[count].image;
    setImage(image);
    allwords = Array.from(maindata[count].otherwords);
    shuffledwords = arrayShuffle(allwords);
    setShuffledwords(shuffledwords);
    const conj = Array.from(maindata[count].conjunction.word);
    correctconj = conj;
    setCorrectconj(correctconj);
    const newArray = generateArray(1, "________");
    setBlankval(newArray);
    splitsentence = typeof sentence === "string" ? sentence.split(" ") : [];
    setSplitsentence(splitsentence);
    disabledBlanks = Array(splitsentence.length).fill(false);
    setDisabledBlanks(disabledBlanks);
    datalength = mainArr.length;
    setDatalength(datalength);
  }

  const generateArray = (length, value) => {
    return Array.from({ length }, () => value);
  };

  const handleOndrop = (e, index) => {
    const id = e.target.id;
    const droppedword = e.dragData[0];
    setFlag2(false)
    if (disabledBlanks[index] === true) {
      return true;
    }
    if (id != "" && !idword.includes(id)) {
      idword = [...idword, id];
      setIdword(idword);
    }
    document.getElementById(id).innerText = e.dragData[0] + "";
    updatedSplitsentence[index] = e.dragData[0];
    setUpdatedSplitsentence(updatedSplitsentence)
    if (splitsentence[index] == updatedSplitsentence[index]) {
      document.getElementById(id).style.backgroundColor = "#098B0D";
      document.getElementById(id).style.color = "white";
      if (!track.includes(e.dragData[0])) {
        track = [...track, e.dragData[0]];
        setTrack(track);
      }
      const updatedDisabledBlanks = [...disabledBlanks];
      updatedDisabledBlanks[index] = true;
      setDisabledBlanks(updatedDisabledBlanks);
      let completesent = "";
      for (let i = 0; i < splitsentence.length; i++) {
        completesent += splitsentence[i];
        if (i < splitsentence.length - 1) {
          completesent += " ";
        }
      }

      ReactGA.event({
        action:
          "English Conjunction | CDAC-OlabsNxtG-En-20 | Dropped correct word",
        category: "English CDAC-OlabsNxtG-En-20 | level-2 dropped correct word",
        label:
          "English CDAC-OlabsNxtG-En-20 | level-2 dropped correct word in current sentence",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        `"${track}"`,
        "Dropped",
        `"${track}" is correct word`,
        [{ input: { droppedword }, answer: { idword }, result: "correct" }]
      );
      setFlag2(true)
      setCurrsentfeedback(
        <div style={{ textAlign: "center" }}>
          Correct!{" "}
          <b style={{ color: "green" }}>{updatedSplitsentence[index]}</b> is
          correct conjunction for this place.
        </div>
      );
    } else {
      document.getElementById(id).style.backgroundColor = " #BF4C4C";
      document.getElementById(id).style.color = "white";
      setFlag2(true)
      setCurrsentfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect!{" "}
          <b style={{ color: "red" }}>{updatedSplitsentence[index]}</b> is not
          correct conjunction for this place.
          <br></br><b>Hint:</b> Here the sentence requires a {" "}
          <b>{corrconjtype}</b>.{" "}
        </div>
      );

      ReactGA.event({
        action:
          "English Conjunction | CDAC-OlabsNxtG-En-20 | Dropped incorrect word",
        category:
          "English CDAC-OlabsNxtG-En-20 | level-2 dropped incorrect word",
        label:
          "English CDAC-OlabsNxtG-En-20 | level-2 dropped incorrect word in current sentence",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        `"${track}"`,
        "Dropped",
        `"${track}" is incorrect word`,
        [{ input: { droppedword }, answer: { idword }, result: "incorrect" }]
      );
    }
  };

  const handleOnclick = (e, index) => {
    if (splitsentence[index] == updatedSplitsentence[index]) {
      setFlag2(true)
      setCurrsentfeedback(
        <div style={{ textAlign: "center" }}>
          Correct!{" "}
          <b style={{ color: "green" }}>{updatedSplitsentence[index]}</b> is
          correct conjunction for this place.
        </div>
      );
    }
    else {
      setFlag2(true)
      setCurrsentfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect!{" "}
          <b style={{ color: "red" }}>{updatedSplitsentence[index]}</b> is not
          the correct conjunction for this place.
          <br></br><b>Hint:</b> Here the sentence requires a {" "}
          <b>{corrconjtype}</b>.{" "}
        </div>
      );
    }
  }

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Restart" button.',
      category:
        'English CDAC-OlabsNxtG-En-20 | level-2 "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-20 | level-2 "Restart" button clicked after level 2 completion',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Restart",
      "Clicked",
      "Click on Restart Button after completion of level 2."
    );
    window.location.reload();
  };

  const nextBtn = () => {
    setProgress(progress + 1);
    count = count + 1;
    setCount(count);
    score = score + 1;
    setScore(score);
    if (count == datalength) {
      flag1 = true;
      setFlag1(flag1);
    } else {
      splitsentence = [];
      setSplitsentence(splitsentence);
      updatedSplitsentence = [];
      setUpdatedSplitsentence(updatedSplitsentence);
      track = [];
      setTrack(track);
      populate(mainArr);
      // To reset the drop field and its background color
      idword.forEach((idword) => {
        splitsentence.forEach((ss) => {
          document.getElementById(idword).innerText = "_______";
          document.getElementById(idword).style.backgroundColor =
            "transparent" + " ";
          document.getElementById(idword).style.color =
            "black" + " ";
        });
      });
      idword = [];
      setIdword(idword);
      setFlag2(false);
      ReactGA.event({
        action:
          'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Next" button.',
        category:
          'English CDAC-OlabsNxtG-En-20 | level-2 "Next" button clicked',
        label:
          'English CDAC-OlabsNxtG-En-20 | level-2 "Next" button clicked for next sentence.',
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        "Next",
        "Clicked",
        "Click on Next Button."
      );
    }
  };

  function arraysAreEqual(arr1, arr2) {
    // Sort the arrays
    const sortedArr1 = arr1.slice().sort();
    const sortedArr2 = arr2.slice().sort();
    if (arr1.length == arr2.length) {
      for (let i = 0; i < arr2.length; i++) {
        if (sortedArr1[i] == sortedArr2[i]) {
          var val = true;
        }
      }
    }
    if (val == true) {
      let completesent = "";
      for (let i = 0; i < splitsentence.length; i++) {
        completesent += splitsentence[i];
        if (i < splitsentence.length - 1) {
          completesent += " ";
        }
      }
      setFlag2(true)
      setCurrsentfeedback(
        <div style={{ textAlign: "center" }}>
          Correct!{" "}
          <b style={{ color: "green" }}>{completesent}</b> is correct sentence.
        </div>
      );
      setTest1(true);
      return true;
    }
  }

  const skipBtn = () => {
    setProgress(progress + 1);
    count = count + 1;
    setCount(count);
    if (count == datalength) {
      flag1 = true;
      setFlag1(flag1);
    } else {
      splitsentence = [];
      setSplitsentence(splitsentence);
      updatedSplitsentence = [];
      setUpdatedSplitsentence(updatedSplitsentence);
      track = [];
      setTrack(track);
      populate(mainArr);

      // To reset the drop field and its background color
      idword.forEach((idword) => {
        splitsentence.forEach((ss) => {
          document.getElementById(idword).innerText = "_______";
          document.getElementById(idword).style.backgroundColor =
            "transparent" + " ";
          document.getElementById(idword).style.color =
            "black" + " ";
        });
      });
      idword = [];
      setIdword(idword);
      setFlag2(false);
      ReactGA.event({
        action:
          'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Skip" button.',
        category:
          'English CDAC-OlabsNxtG-En-20 | level-2 "Skip" button clicked',
        label:
          'English CDAC-OlabsNxtG-En-20 | level-2 "Skip" button clicked for next sentence.',
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "Skip",
        "Clicked",
        "Click on Skip Button."
      );
    }
  };

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        ReactGA.event({
          action:
            'English Conjunction | CDAC-OlabsNxtG-En-20 | clicked on "Level 1" button.',
          category:
            'English CDAC-OlabsNxtG-En-20 | level-2 "Level 1" button clicked',
          label:
            'English CDAC-OlabsNxtG-En-20 | level-2 "Level 1" button clicked from levels dropdown',
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Level 1 dropdown option",
          "Clicked",
          "Click on Level 1 Button from levels dropdown."
        );
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
  };

  return (
    <div
      className="row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag1 ? (
          <div
            className=""
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row d-flex">
              <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
                <b>{t("level_2_title")}</b>
              </div>
              <div className="col-md-auto d-flex justify-content-end">
                <FormControl size="small" sx={{ minWidth: 120 }}>
                  <Select
                    labelId="demo-simple-select-label"
                    id="demo-simple-select"
                    value={level}
                    onChange={handleLevelChange}
                    sx={{
                      bgcolor: "green",
                      borderRadius: 1,
                      "& .MuiOutlinedInput-notchedOutline": {
                        borderColor: "green",
                      },
                      color: "white",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                    <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                  </Select>
                </FormControl>
              </div>
            </div>
            <div className="row" style={{ height: "80%" }}>
              <div className="d-flex justify-content-center align-items-center">
                <div
                  className="col-md-auto text-center "
                  style={{
                    boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                    padding: "7vh 4vh 7vh 4vh",
                    backgroundColor: "#EDF6FA",
                    fontSize: "calc(.6rem + .4vw)"
                  }}
                >
                  <p style={{ fontWeight: "bolder" }}>
                    You have scored {score} out of 10 sentences.
                  </p>
                  <div>
                    <Button variant="contained" onClick={restartbtn} style={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}>
                      {t("restart")}
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className=""
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex">
              <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
                <b>{t("level_2_title")}</b>
              </div>

              <div className="d-flex justify-content-end">
                <FormControl size="small" sx={{ minWidth: 120 }}>
                  <Select
                    labelId="demo-simple-select-label"
                    id="demo-simple-select"
                    value={level}
                    onChange={handleLevelChange}
                    sx={{
                      bgcolor: "green",
                      borderRadius: 1,
                      "& .MuiOutlinedInput-notchedOutline": {
                        borderColor: "green",
                      },
                      color: "white",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                    <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                  </Select>
                </FormControl>
              </div>
            </div>
            <div className="row">
              <div className="">
                <div
                  className="d-flex align-items-center"
                  style={{ marginTop: "5vh", fontSize: "calc(.6rem + .4vw)" }}
                >
                  <span className="me-3">Sentence</span>

                  <Slider
                    defaultValue={1}
                    step={1}
                    min={1}
                    max={datalength}
                    value={progress + 1}
                    color="success"
                    marks
                    valueLabelDisplay="on"
                    sx={{
                      "& .MuiSlider-mark": {
                        width: 12,
                        height: 12,
                        borderRadius: "50%",
                      },
                    }}
                  />

                  <span
                    className="ms-3"
                    style={{
                      height: "40px",
                      width: "60px",
                      borderRadius: "50%",
                      backgroundColor: "lightblue",
                      fontSize: "16px",
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    {count + 1}/{datalength}
                  </span>
                </div>
              </div>
              <div className="">
                <div className="text-center">
                  <div
                    className="row-md-auto text-center"
                    style={{
                      backgroundColor: "#D6EAF8",
                      borderRadius: "13px",
                      boxShadow: "0px 4px 7px #00000029",
                      display: "block",
                      marginLeft: "auto",
                      marginRight: "auto",
                      marginTop: "1%",
                      padding: "1%",
                      fontWeight: "bolder",
                      fontFamily: "Arial",
                      backgroundColor: "#EDF6FA",
                      cursor: "pointer",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    {twoSentence}
                  </div>

                  <div
                    className="row-md-auto text-center"
                    style={{
                      backgroundColor: "#D6EAF8",
                      borderRadius: "13px",
                      boxShadow: "0px 4px 7px #00000029",
                      display: "block",
                      marginLeft: "auto",
                      marginRight: "auto",
                      marginTop: "2%",
                      marginBottom: "1%",
                      padding: "1%",
                      fontWeight: "bolder",
                      fontFamily: "Arial",
                      backgroundColor: "#EDF6FA",
                      cursor: "pointer",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    {splitsentence.map((word, i) =>
                      correctconj.includes(word) ? (
                        <DropTarget
                          key={"dropTarget" + i}
                          targetKey=""
                          onHit={(e) => handleOndrop(e, i)}

                        >
                          <span
                            wrap="hard"
                            id={word}
                            onDragOver={(e) => e.preventDefault()}
                            className={
                              conditionMatches ? "reset-css" : "default-css"
                            }
                            style={{
                              padding: "1vh",
                              borderRadius: "5px",
                              disabled: disabledBlanks[i],
                            }}
                            onClick={(e) => handleOnclick(e, i)}
                          >
                            &nbsp;{"_______"}&nbsp;
                          </span>
                        </DropTarget>
                      ) : (
                        <span key={i}> {word} </span>
                      )
                    )}
                  </div>
                </div>
              </div>
              <div className="row d-flex justify-content-around">
                <div className="col-lg-6 col-md-6 col-sm-12 ">
                  <div
                    className="col-md-auto "
                    style={{
                      borderRadius: "2%",
                      padding: "5%",
                      margin: "5%",
                      backgroundColor: "#EDF6FA",
                      boxShadow: "0px 4px 7px #00000029",
                    }}
                  >
                    <div style={{ textAlign: "start", fontSize: "calc(.6rem + .4vw)" }}>
                      <span style={{}}>Wordpool</span>
                    </div>
                    <div className="d-flex justify-content-around align-items-center mt-2"> <div className="col">
                      {shuffledwords &&
                        shuffledwords.slice(0, 3).map((item, index) => (
                          <Grid
                            key={"grid" + index}
                            className="d-flex justify-content-center align-items-center"
                            container
                            spacing={1}
                            style={{ marginBottom: "3%" }}
                          >
                            <Grid item s={4}>
                              <DragDropContainer targetKey="" dragData={[item]}>
                                <Button
                                  key={index}
                                  style={{
                                    background:
                                      "#F5B946",
                                    borderRadius: "5px",
                                    textAlign: "center",
                                    boxSizing: "border-box",
                                    textTransform: "none",
                                    color: "black",
                                    padding: "15%",
                                    cursor: "grabbing",
                                    fontSize: "calc(.6rem + .4vw)"
                                  }}
                                >
                                  {item}
                                </Button>
                              </DragDropContainer>
                            </Grid>
                          </Grid>
                        ))}
                    </div>

                      <div className="col">
                        {shuffledwords &&
                          shuffledwords.slice(3, 6).map((item, index) => (
                            <Grid
                              key={"grid1" + index}
                              className="d-flex justify-content-center align-items-center"
                              container
                              spacing={1}
                              style={{ marginBottom: "3%" }}
                            >
                              <Grid item s={4}>
                                <DragDropContainer targetKey="" dragData={[item]}>
                                  <Button
                                    style={{
                                      background:
                                        "#F5B946",
                                      borderRadius: "5px",
                                      textAlign: "center",
                                      boxSizing: "border-box",
                                      textTransform: "none",
                                      color: "black",
                                      padding: "15%",
                                      cursor: "grabbing",
                                      fontSize: "calc(.6rem + .4vw)"
                                    }}
                                  >
                                    {item}
                                  </Button>
                                </DragDropContainer>
                              </Grid>
                            </Grid>
                          ))}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="col-lg-6 col-md-6 col-sm-12 d-flex justify-content-center align-items-center">
                  {image && (
                    <img
                      className="img-fluid"
                      src={require(`../Images/${image}`)}
                      alt="Activity Visual"
                      style={{ height: '80%', maxWidth: '100%', objectFit: 'contain' }}
                    />
                  )}
                </div>
              </div>
              <div className="d-flex justify-content-around">
                <div className="d-flex justify-content-around">
                  <Button
                    variant="contained"
                    onClick={skipBtn}
                    disabled={isCorrect}
                    sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
                  >
                    {t("skip")}
                  </Button>
                </div>
                <div className="d-flex justify-content-around">
                  <Button
                    variant="contained"
                    onClick={nextBtn}
                    disabled={!isCorrect}
                    sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
                  >
                    {t("next")}
                  </Button>
                </div>
              </div>

              <div
                className="row justify-content-center"
                style={{ marginTop: "2vh" }}
              >
                {flag2 ? (
                  <div
                    className="d-flex justify-content-center align-items-center"
                    style={{
                      width: "auto",
                      height: "auto",
                      background: "rgb(255, 255, 255)",
                      boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                      borderRadius: "50px",
                      padding: "1rem",
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    {currsentfeedback}
                  </div>
                ) : (
                  ""
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className=""
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", fontSize: "calc(.6rem + .4vw)" }}>
            <div>
              {flag1 == true ? (
                <ul className="">
                  <li>{t("instruction_2_9")}</li>
                </ul>
              ) : isCorrect == true ? (
                <ul className="">
                  <li>{t("instruction_2_7")}</li>
                </ul>
              ) : (
                <ul className="">
                  <li>{t("instruction_2_1")}</li>
                  <li>{t("instruction_2_2")}</li>
                  <li>{t("instruction_2_3")}</li>
                  <li>{t("instruction_2_4")}</li>
                  <li>{t("instruction_2_5")}</li>
                  <li>{t("instruction_2_6")}</li>
                  <li><u>{t("note")}</u>: {t("instruction_2_8")}</li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level2;
